"use client";

import { useCallback, useEffect, useMemo, useState, type FormEvent, type ReactNode } from "react";
import {
  ArrowDownLeft, ArrowLeftRight, ArrowUpRight, BarChart3, Bell, Check, ChevronRight, CircleDollarSign,
  CreditCard, Download, FileDown, Home, Landmark, LayoutDashboard, Menu, MoreHorizontal, Pencil, Plus,
  Search, Settings, ShieldCheck, Target, Trash2, TrendingDown, TrendingUp, UserRound, Wallet, X, Zap,
} from "lucide-react";
import { Area, AreaChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis, BarChart, Bar } from "recharts";

type AnyRecord = Record<string, any>;
type DashboardData = {
  profile: AnyRecord; settings: AnyRecord | null; accounts: AnyRecord[]; categories: AnyRecord[]; transactions: AnyRecord[];
  receivables: AnyRecord[]; debts: AnyRecord[]; bills: AnyRecord[]; goals: AnyRecord[]; settlement: AnyRecord | null;
  totals: AnyRecord; today: AnyRecord; month: AnyRecord; chart: AnyRecord[]; upcomingBills: AnyRecord[]; upcomingDebts: AnyRecord[]; alerts: AnyRecord[];
};

type Section = "dashboard" | "accounts" | "transactions" | "receivables" | "debts" | "bills" | "goals" | "reports" | "personal" | "settings";

const navItems: { id: Section; label: string; icon: typeof Home }[] = [
  { id: "dashboard", label: "Dashboard", icon: LayoutDashboard },
  { id: "accounts", label: "Meu Dinheiro", icon: Wallet },
  { id: "transactions", label: "Movimentações", icon: ArrowLeftRight },
  { id: "receivables", label: "A Receber", icon: ArrowDownLeft },
  { id: "debts", label: "Dívidas", icon: CreditCard },
  { id: "bills", label: "Contas a Pagar", icon: Landmark },
  { id: "goals", label: "Metas", icon: Target },
  { id: "reports", label: "Relatórios", icon: BarChart3 },
  { id: "personal", label: "Pessoal x GBR", icon: UserRound },
  { id: "settings", label: "Configurações", icon: Settings },
];

const currency = new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" });
const dateFormatter = new Intl.DateTimeFormat("pt-BR", { day: "2-digit", month: "short" });
const fullDateFormatter = new Intl.DateTimeFormat("pt-BR", { day: "2-digit", month: "2-digit", year: "numeric" });

function money(value: unknown) { return currency.format(Number(value ?? 0)); }
function date(value: unknown) { if (!value) return "—"; const parsed = new Date(String(value)); return Number.isNaN(parsed.getTime()) ? String(value) : fullDateFormatter.format(parsed); }
function shortDate(value: unknown) { if (!value) return "—"; const parsed = new Date(String(value)); return Number.isNaN(parsed.getTime()) ? String(value) : dateFormatter.format(parsed); }
function initials(name: string) { return name.split(" ").slice(0, 2).map((part) => part[0]).join("").toUpperCase(); }
function labelType(type: string) { return ({ physical: "Físico", digital: "Digital", investment: "Investimentos", other: "Outro" } as AnyRecord)[type] ?? type; }
function labelOrigin(origin: string) { return origin === "gbr" ? "GBR Soluções" : "Pessoal"; }

async function api(path: string, options?: RequestInit) {
  const response = await fetch(path, { ...options, headers: { "Content-Type": "application/json", ...(options?.headers ?? {}) } });
  const payload = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(payload.error || "Não foi possível concluir a operação.");
  return payload;
}

function Button({ children, className = "", ...props }: React.ButtonHTMLAttributes<HTMLButtonElement>) {
  return <button className={`transition ${className}`} {...props}>{children}</button>;
}
function Money({ value, className = "" }: { value: unknown; className?: string }) { return <span className={className}>{money(value)}</span>; }
function SectionHeading({ title, description, action }: { title: string; description?: string; action?: ReactNode }) {
  return <div className="mb-5 flex items-end justify-between gap-4"><div><h2 className="text-[19px] font-semibold tracking-[-.02em] text-white">{title}</h2>{description && <p className="mt-1 text-sm text-muted">{description}</p>}</div>{action}</div>;
}
function Empty({ title, description, action }: { title: string; description: string; action?: ReactNode }) {
  return <div className="surface-soft flex min-h-[170px] flex-col items-center justify-center rounded-2xl px-5 py-8 text-center"><div className="mb-3 rounded-2xl bg-[#18322d] p-3 text-[#61daba]"><CircleDollarSign size={21} /></div><p className="text-sm font-medium text-white">{title}</p><p className="mt-1 max-w-xs text-xs leading-5 text-muted">{description}</p>{action && <div className="mt-4">{action}</div>}</div>;
}
function Progress({ value, color = "#41d8b2" }: { value: number; color?: string }) { return <div className="h-2 overflow-hidden rounded-full bg-white/[.07]"><div className="h-full rounded-full transition-all" style={{ width: `${Math.min(100, Math.max(0, value))}%`, background: color }} /></div>; }

export default function HomePage() {
  const [data, setData] = useState<DashboardData | null>(null);
  const [active, setActive] = useState<Section>("dashboard");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [toast, setToast] = useState("");
  const [quickOpen, setQuickOpen] = useState(false);
  const [search, setSearch] = useState("");
  const [mobileMenu, setMobileMenu] = useState(false);

  const refresh = useCallback(async () => {
    try { setError(""); const next = await api("/api/dashboard"); setData(next); }
    catch (err) { setError(err instanceof Error ? err.message : "Não foi possível carregar o painel."); }
    finally { setLoading(false); }
  }, []);

  useEffect(() => { refresh(); }, [refresh]);
  useEffect(() => { if (!toast) return; const timer = window.setTimeout(() => setToast(""), 3500); return () => window.clearTimeout(timer); }, [toast]);

  async function run(action: () => Promise<unknown>, success = "Alterações salvas.") {
    try { await action(); await refresh(); setToast(success); }
    catch (err) { setToast(err instanceof Error ? err.message : "Não foi possível salvar."); }
  }

  if (loading) return <LoadingScreen />;
  if (error || !data) return <ErrorScreen message={error} retry={refresh} />;

  const searchResults = search.trim() ? data.transactions.filter((row) => `${row.description ?? ""} ${row.note ?? ""}`.toLowerCase().includes(search.toLowerCase())).slice(0, 5) : [];
  const go = (section: Section) => { setActive(section); setMobileMenu(false); window.scrollTo({ top: 0, behavior: "smooth" }); };

  return <div className="app-shell flex min-h-screen">
    <Sidebar active={active} onNavigate={go} mobileOpen={mobileMenu} onClose={() => setMobileMenu(false)} profile={data.profile} />
    <main className="min-w-0 flex-1 md:ml-[248px]">
      <header className="sticky top-0 z-30 border-b border-white/[.06] bg-[#07100f]/90 px-4 py-4 backdrop-blur-xl sm:px-6 lg:px-9">
        <div className="mx-auto flex max-w-[1440px] items-center gap-3">
          <Button className="rounded-xl border border-white/[.09] p-2 text-muted md:hidden" onClick={() => setMobileMenu(true)} aria-label="Abrir menu"><Menu size={20} /></Button>
          <div className="relative min-w-0 flex-1 md:max-w-[390px]"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-muted" size={17} /><input value={search} onChange={(event) => setSearch(event.target.value)} className="input-dark pl-10" placeholder="Buscar no GBR Bank..." />
            {searchResults.length > 0 && <div className="surface absolute left-0 right-0 top-[calc(100%+10px)] z-40 rounded-2xl p-2">{searchResults.map((row) => <button key={row.id} onClick={() => { setSearch(""); go("transactions"); }} className="flex w-full items-center justify-between rounded-xl px-3 py-2 text-left hover:bg-white/[.05]"><span className="truncate text-sm text-white">{row.description || "Movimentação"}</span><span className={`ml-3 shrink-0 text-sm ${row.type === "income" ? "text-mint" : "text-red"}`}>{row.type === "income" ? "+" : "−"}{money(row.amount)}</span></button>)}</div>}
          </div>
          <div className="hidden items-center gap-2 sm:flex"><div className="rounded-full border border-white/[.08] p-2 text-muted"><Bell size={17} /></div><button onClick={() => go("settings")} className="flex items-center gap-2 rounded-full border border-white/[.08] py-1.5 pl-1.5 pr-3 hover:bg-white/[.05]"><span className="grid h-7 w-7 place-items-center rounded-full bg-[#2d8973] text-xs font-bold text-white">{initials(data.profile.name)}</span><span className="text-sm text-white">{data.profile.name}</span></button></div>
        </div>
      </header>
      <div className="mx-auto max-w-[1440px] px-4 py-7 pb-28 sm:px-6 lg:px-9 lg:py-9">
        <div className="mb-8 flex flex-wrap items-end justify-between gap-4"><div><p className="mb-2 text-xs font-semibold uppercase tracking-[.19em] text-mint">{active === "dashboard" ? "Visão geral" : "GBR Bank"}</p><h1 className="text-2xl font-semibold tracking-[-.035em] text-white sm:text-[30px]">{active === "dashboard" ? `Olá, ${data.profile.name.split(" ")[0]}!` : navItems.find((item) => item.id === active)?.label}</h1><p className="mt-1 text-sm text-muted">{active === "dashboard" ? "Resumo da sua vida financeira" : "Controle simples, claro e sempre ao seu alcance."}</p></div><div className="flex items-center gap-3"><span className="hidden text-sm text-muted sm:block">{new Intl.DateTimeFormat("pt-BR", { weekday: "long", day: "numeric", month: "long" }).format(new Date())}</span><Button className="mobile-quick-trigger btn-primary flex items-center gap-2 text-sm" onClick={() => setQuickOpen(true)}><Plus size={17} strokeWidth={2.5} /> Lançar movimentação</Button></div></div>
        {active === "dashboard" && <DashboardView data={data} onNavigate={go} onRefresh={refresh} run={run} />}
        {active === "accounts" && <AccountsView data={data} run={run} />}
        {active === "transactions" && <TransactionsView data={data} run={run} />}
        {active === "receivables" && <ReceivablesView data={data} run={run} />}
        {active === "debts" && <DebtsView data={data} run={run} />}
        {active === "bills" && <BillsView data={data} run={run} />}
        {active === "goals" && <GoalsView data={data} run={run} />}
        {active === "reports" && <ReportsView data={data} />}
        {active === "personal" && <PersonalView data={data} />}
        {active === "settings" && <SettingsView data={data} run={run} />}
      </div>
    </main>
    <Button className="fixed bottom-5 right-5 z-20 flex items-center gap-2 rounded-full bg-[#41d8b2] px-4 py-3 text-sm font-bold text-[#05251d] shadow-[0_10px_35px_rgba(65,216,178,.25)] md:hidden" onClick={() => setQuickOpen(true)}><Zap size={16} fill="currentColor" /> Lançar</Button>
    {quickOpen && <QuickModal data={data} onClose={() => setQuickOpen(false)} onDone={(message) => { setQuickOpen(false); run(async () => undefined, message); }} onNavigate={go} />}
    {toast && <div className="fixed bottom-5 left-1/2 z-[80] flex max-w-[calc(100%-32px)] -translate-x-1/2 items-center gap-2 rounded-xl border border-white/10 bg-[#162b27] px-4 py-3 text-sm text-white shadow-2xl"><Check size={16} className="text-mint" />{toast}</div>}
  </div>;
}

function LoadingScreen() { return <div className="grid min-h-screen place-items-center bg-[#07100f] text-center"><div><div className="mx-auto mb-5 grid h-14 w-14 place-items-center rounded-2xl bg-[#41d8b2] text-xl font-black text-[#06251d]">GB</div><p className="text-sm text-muted">Preparando sua visão financeira...</p></div></div>; }
function ErrorScreen({ message, retry }: { message: string; retry: () => void }) { return <div className="grid min-h-screen place-items-center bg-[#07100f] px-6 text-center"><div className="surface max-w-md rounded-3xl p-8"><div className="mx-auto mb-4 grid h-12 w-12 place-items-center rounded-2xl bg-[#3a201e] text-red"><ShieldCheck size={22} /></div><h1 className="text-xl font-semibold text-white">Não foi possível abrir o GBR Bank</h1><p className="mt-2 text-sm leading-6 text-muted">{message || "Verifique a conexão com o PostgreSQL e tente novamente."}</p><Button className="btn-primary mt-6" onClick={retry}>Tentar novamente</Button></div></div>; }

function Sidebar({ active, onNavigate, mobileOpen, onClose, profile }: { active: Section; onNavigate: (id: Section) => void; mobileOpen: boolean; onClose: () => void; profile: AnyRecord }) {
  return <><div className={`fixed inset-0 z-40 bg-black/60 md:hidden ${mobileOpen ? "block" : "hidden"}`} onClick={onClose} /><aside className={`fixed inset-y-0 left-0 z-50 flex w-[248px] flex-col border-r border-white/[.07] bg-[#091513] px-4 py-5 transition-transform md:translate-x-0 ${mobileOpen ? "translate-x-0" : "-translate-x-full"}`}><div className="flex items-center justify-between px-3"><button onClick={() => onNavigate("dashboard")} className="flex items-center gap-3 text-left"><span className="grid h-9 w-9 place-items-center rounded-xl bg-[#41d8b2] text-sm font-black tracking-tight text-[#05251d]">GB</span><span><span className="block text-[15px] font-bold tracking-wide text-white">GBR <span className="text-mint">BANK</span></span><span className="block text-[10px] text-muted">Meu dinheiro. Minha visão.</span></span></button><Button onClick={onClose} className="rounded-lg p-1 text-muted md:hidden"><X size={18} /></Button></div><div className="my-6 h-px bg-white/[.07]" /><nav className="scrollbar-thin flex-1 space-y-1 overflow-y-auto">{navItems.map(({ id, label, icon: Icon }) => <button key={id} onClick={() => onNavigate(id)} className={`flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-[13px] font-medium transition ${active === id ? "bg-[#173d34] text-[#70e8c5]" : "text-muted hover:bg-white/[.04] hover:text-white"}`}><Icon size={17} strokeWidth={active === id ? 2.3 : 1.8} />{label}{id === "dashboard" && <span className="ml-auto h-1.5 w-1.5 rounded-full bg-mint" />}</button>)}</nav><div className="mt-5 rounded-2xl border border-[#24574a] bg-[#102a24] p-3.5"><div className="mb-2 flex items-center gap-2 text-mint"><ShieldCheck size={15} /><span className="text-xs font-semibold">Ambiente privado</span></div><p className="text-[11px] leading-4 text-[#91b4aa]">Seus dados ficam no PostgreSQL configurado para o GBR Bank.</p></div><button onClick={() => onNavigate("settings")} className="mt-4 flex items-center gap-3 border-t border-white/[.07] px-3 pt-4 text-left"><span className="grid h-8 w-8 place-items-center rounded-full bg-[#2d8973] text-xs font-bold text-white">{initials(profile.name)}</span><span className="min-w-0"><span className="block truncate text-xs font-semibold text-white">{profile.name}</span><span className="block truncate text-[10px] text-muted">{profile.email}</span></span><MoreHorizontal size={16} className="ml-auto text-muted" /></button></aside></>;
}

function DashboardView({ data, onNavigate, run }: { data: DashboardData; onNavigate: (id: Section) => void; onRefresh: () => void; run: (action: () => Promise<unknown>, success?: string) => Promise<void> }) {
  return <div className="fade-in space-y-6"><div className="grid gap-4 lg:grid-cols-[1.35fr_1fr_1fr]"><div className="relative overflow-hidden rounded-2xl bg-gradient-to-br from-[#1c6251] via-[#154438] to-[#10241f] p-5 shadow-[0_22px_48px_rgba(26,112,90,.16)] sm:p-6"><div className="absolute -right-10 -top-14 h-44 w-44 rounded-full border-[24px] border-white/[.05]" /><div className="relative"><div className="flex items-center justify-between"><p className="text-sm font-medium text-[#b1e7d7]">Meu dinheiro</p><span className="rounded-lg bg-white/10 p-2 text-[#9ff0d9]"><Wallet size={18} /></span></div><p className="mt-5 text-[32px] font-semibold tracking-[-.05em] text-white sm:text-[38px]"><Money value={data.totals.available} /></p><p className="mt-1 text-xs text-[#a3d3c7]">Saldo disponível em contas ativas</p><div className="mt-6 grid grid-cols-3 gap-2 border-t border-white/10 pt-4"><div><p className="text-[10px] uppercase tracking-wider text-[#94cabc]">Físico</p><p className="mt-1 text-sm font-semibold text-white"><Money value={data.totals.physical} /></p></div><div><p className="text-[10px] uppercase tracking-wider text-[#94cabc]">Digital</p><p className="mt-1 text-sm font-semibold text-white"><Money value={data.totals.digital} /></p></div><div><p className="text-[10px] uppercase tracking-wider text-[#94cabc]">Investido</p><p className="mt-1 text-sm font-semibold text-white"><Money value={data.totals.investments} /></p></div></div></div></div><MetricCard title="A receber" value={data.totals.toReceive} icon={<ArrowDownLeft size={18} />} tone="mint" caption={`${data.receivables.filter((row) => row.remainingAmount > 0).length} valores pendentes`} onClick={() => onNavigate("receivables")} /><MetricCard title="Minhas dívidas" value={data.totals.debtTotal} icon={<ArrowUpRight size={18} />} tone="orange" caption={`${data.debts.filter((row) => row.remainingAmount > 0).length} compromissos em aberto`} onClick={() => onNavigate("debts")} /></div><div className="grid gap-6 xl:grid-cols-[1.55fr_1fr]"><div className="surface rounded-2xl p-5 sm:p-6"><div className="mb-5 flex items-start justify-between"><div><p className="text-sm font-medium text-muted">Evolução financeira</p><h2 className="mt-1 text-xl font-semibold text-white">Visão dos últimos 7 dias</h2></div><button onClick={() => onNavigate("reports")} className="flex items-center gap-1 text-xs font-semibold text-mint">Ver relatório <ChevronRight size={14} /></button></div><div className="h-[240px] w-full"><ResponsiveContainer width="100%" height="100%"><AreaChart data={data.chart} margin={{ top: 8, right: 4, left: -24, bottom: 0 }}><defs><linearGradient id="incomeFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#41d8b2" stopOpacity={.25} /><stop offset="100%" stopColor="#41d8b2" stopOpacity={0} /></linearGradient><linearGradient id="expenseFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#ff9a65" stopOpacity={.2} /><stop offset="100%" stopColor="#ff9a65" stopOpacity={0} /></linearGradient></defs><CartesianGrid vertical={false} stroke="rgba(160,190,182,.08)" /><XAxis dataKey="day" axisLine={false} tickLine={false} tick={{ fill: "#718b85", fontSize: 11 }} /><YAxis axisLine={false} tickLine={false} tick={{ fill: "#718b85", fontSize: 10 }} tickFormatter={(value) => value >= 1000 ? `${(value / 1000).toFixed(0)}k` : value} /><Tooltip content={<ChartTooltip />} /><Area type="monotone" dataKey="income" name="Entradas" stroke="#41d8b2" strokeWidth={2.5} fill="url(#incomeFill)" /><Area type="monotone" dataKey="expense" name="Saídas" stroke="#ff9a65" strokeWidth={2} fill="url(#expenseFill)" /></AreaChart></ResponsiveContainer></div><div className="mt-2 flex gap-5 text-xs text-muted"><span className="flex items-center gap-2"><i className="h-2 w-2 rounded-full bg-mint" />Entradas</span><span className="flex items-center gap-2"><i className="h-2 w-2 rounded-full bg-[#ff9a65]" />Saídas</span></div></div><div className="surface rounded-2xl p-5 sm:p-6"><SectionHeading title="Patrimônio líquido" description="Disponível + recebíveis − dívidas" /><p className={`text-[31px] font-semibold tracking-[-.05em] ${Number(data.totals.netWorth) >= 0 ? "text-white" : "text-red"}`}><Money value={data.totals.netWorth} /></p><div className="mt-5 space-y-3"><div className="flex justify-between text-xs"><span className="text-muted">Dinheiro disponível</span><span className="text-white"><Money value={data.totals.available} /></span></div><div className="flex justify-between text-xs"><span className="text-muted">A receber</span><span className="text-mint"><Money value={data.totals.toReceive} /></span></div><div className="h-px bg-white/[.08]" /><div className="flex justify-between text-xs"><span className="text-muted">Dívidas</span><span className="text-orange">− <Money value={data.totals.debtTotal} /></span></div></div><div className="mt-6 rounded-xl bg-[#122923] px-3 py-3 text-xs leading-5 text-[#a5c7be]">Este número mostra o que realmente sobra considerando o que você tem a receber e o que precisa pagar.</div></div></div><div className="grid gap-6 lg:grid-cols-[1fr_1.15fr]"><div className="surface rounded-2xl p-5 sm:p-6"><SectionHeading title="Resultado do dia" description="Entradas menos saídas" action={<span className={`text-sm font-semibold ${data.today.result >= 0 ? "text-mint" : "text-red"}`}>{data.today.result >= 0 ? "+" : "−"}<Money value={Math.abs(data.today.result)} /></span>} /><div className="grid grid-cols-3 gap-2"><MiniStat label="Entradas" value={data.today.income} color="text-mint" icon={<ArrowDownLeft size={14} />} /><MiniStat label="Saídas" value={data.today.expense} color="text-orange" icon={<ArrowUpRight size={14} />} /><MiniStat label="Movimentações" value={data.today.total} color="text-white" icon={<ArrowLeftRight size={14} />} numeric /></div><div className="mt-5 flex justify-between text-xs text-muted"><span>{data.today.incomeCount} entradas</span><span>{data.today.expenseCount} saídas</span><span>{data.today.total} no total</span></div></div><div className="surface rounded-2xl p-5 sm:p-6"><SectionHeading title="Resumo do mês" description={`Resultado acumulado em ${new Intl.DateTimeFormat("pt-BR", { month: "long" }).format(new Date())}`} action={<button onClick={() => onNavigate("reports")} className="text-xs text-mint">Detalhes</button>} /><div className="grid grid-cols-3 gap-3"><div><p className="text-xs text-muted">Receitas</p><p className="mt-1 text-lg font-semibold text-mint"><Money value={data.month.income} /></p></div><div><p className="text-xs text-muted">Despesas</p><p className="mt-1 text-lg font-semibold text-orange"><Money value={data.month.expense} /></p></div><div><p className="text-xs text-muted">Resultado</p><p className={`mt-1 text-lg font-semibold ${data.month.result >= 0 ? "text-white" : "text-red"}`}><Money value={data.month.result} /></p></div></div><div className="mt-5 h-1.5 overflow-hidden rounded-full bg-[#20332f]"><div className="h-full rounded-full bg-gradient-to-r from-[#41d8b2] to-[#9be7b2]" style={{ width: `${data.month.income ? Math.min(100, Math.max(8, (data.month.result / data.month.income) * 100)) : 8}%` }} /></div><p className="mt-2 text-[11px] text-muted">{data.month.income ? `${Math.round((Math.max(0, data.month.result) / data.month.income) * 100)}% da receita ficou disponível` : "Comece registrando sua primeira movimentação"}</p></div></div><div className="grid gap-6 xl:grid-cols-3"><ListCard title="Próximos vencimentos" action={<button onClick={() => onNavigate("bills")} className="text-xs text-mint">Ver contas</button>}>{data.upcomingBills.length ? data.upcomingBills.slice(0, 4).map((bill) => <SimpleRow key={bill.id} icon={<Landmark size={16} />} title={bill.name} subtitle={`Vence em ${shortDate(bill.dueDate)}`} value={bill.amount} tone="orange" />) : <Empty title="Nenhuma conta pendente" description="Suas obrigações futuras aparecerão aqui." action={<Button className="btn-secondary text-xs" onClick={() => onNavigate("bills")}>Adicionar conta</Button>} />}</ListCard><ListCard title="A receber" action={<button onClick={() => onNavigate("receivables")} className="text-xs text-mint">Ver tudo</button>}>{data.receivables.filter((row) => row.remainingAmount > 0).slice(0, 4).length ? data.receivables.filter((row) => row.remainingAmount > 0).slice(0, 4).map((row) => <SimpleRow key={row.id} icon={<ArrowDownLeft size={16} />} title={row.person} subtitle={row.description} value={row.remainingAmount} tone="mint" />) : <Empty title="Tudo em dia" description="Valores que você tem a receber ficam visíveis nesta lista." action={<Button className="btn-secondary text-xs" onClick={() => onNavigate("receivables")}>Adicionar recebível</Button>} />}</ListCard><ListCard title="Minhas metas" action={<button onClick={() => onNavigate("goals")} className="text-xs text-mint">Gerenciar</button>}>{data.goals.length ? data.goals.slice(0, 3).map((goal) => <div key={goal.id} className="mb-4 last:mb-0"><div className="mb-2 flex items-center justify-between gap-3"><span className="truncate text-sm text-white">{goal.name}</span><span className="text-xs font-semibold text-mint">{goal.progress}%</span></div><Progress value={goal.progress} /><div className="mt-1.5 flex justify-between text-[10px] text-muted"><span><Money value={goal.currentAmount} /> acumulados</span><span>meta <Money value={goal.targetAmount} /></span></div></div>) : <Empty title="Crie sua primeira meta" description="Acompanhe o que você quer conquistar, sem complicar." action={<Button className="btn-secondary text-xs" onClick={() => onNavigate("goals")}>Criar meta</Button>} />}</ListCard></div><div className="grid gap-6 lg:grid-cols-[1.25fr_1fr]"><div className="surface rounded-2xl p-5 sm:p-6"><SectionHeading title="Últimas movimentações" action={<button onClick={() => onNavigate("transactions")} className="text-xs text-mint">Ver todas</button>} />{data.transactions.filter((row) => row.type !== "transfer").slice(0, 5).length ? <div className="space-y-1">{data.transactions.filter((row) => row.type !== "transfer").slice(0, 5).map((row) => <TransactionRow key={row.id} row={row} data={data} />)}</div> : <Empty title="Nenhuma movimentação ainda" description="Registre sua primeira entrada ou saída em poucos segundos." />}</div><div className="surface rounded-2xl p-5 sm:p-6"><SectionHeading title="Meu acerto" action={<button onClick={() => onNavigate("personal")} className="text-xs text-mint">Ajustar</button>} />{data.settlement ? <><div className="mb-4 flex items-end justify-between"><div><p className="text-xs text-muted">Já separado</p><p className="mt-1 text-2xl font-semibold text-white"><Money value={data.settlement.savedAmount} /></p></div><div className="text-right"><p className="text-xs text-muted">Falta</p><p className="mt-1 text-lg font-semibold text-orange"><Money value={data.settlement.remainingAmount} /></p></div></div><Progress value={data.settlement.progress} color="#ff9a65" /><div className="mt-2 flex justify-between text-xs text-muted"><span>{data.settlement.progress}% concluído</span><span>Meta <Money value={data.settlement.targetAmount} /></span></div></> : <Empty title="Defina um acerto" description="Separe um valor para colocar sua vida financeira em ordem." />}</div></div></div>;
}

function MetricCard({ title, value, icon, tone, caption, onClick }: { title: string; value: unknown; icon: ReactNode; tone: "mint" | "orange"; caption: string; onClick: () => void }) { return <button onClick={onClick} className="surface rounded-2xl p-5 text-left transition hover:-translate-y-0.5 hover:border-white/20"><div className="flex items-center justify-between"><span className="text-sm font-medium text-muted">{title}</span><span className={`rounded-lg p-2 ${tone === "mint" ? "bg-[#163c33] text-mint" : "bg-[#3a2b23] text-orange"}`}>{icon}</span></div><p className="mt-5 text-[25px] font-semibold tracking-[-.04em] text-white"><Money value={value} /></p><p className="mt-1 text-xs text-muted">{caption}</p></button>; }
function MiniStat({ label, value, color, icon, numeric }: { label: string; value: unknown; color: string; icon: ReactNode; numeric?: boolean }) { return <div className="rounded-xl bg-white/[.035] p-3"><div className={`mb-2 flex items-center gap-1.5 text-[11px] ${color}`}>{icon}{label}</div><p className={`font-semibold ${numeric ? "text-lg" : "text-sm"} ${color}`}>{numeric ? String(value ?? 0) : <Money value={value} />}</p></div>; }
function ListCard({ title, action, children }: { title: string; action?: ReactNode; children: ReactNode }) { return <div className="surface rounded-2xl p-5"><div className="mb-4 flex items-center justify-between"><h3 className="font-semibold text-white">{title}</h3>{action}</div>{children}</div>; }
function SimpleRow({ icon, title, subtitle, value, tone }: { icon: ReactNode; title: string; subtitle: string; value: unknown; tone: "mint" | "orange" }) { return <div className="flex items-center gap-3 border-b border-white/[.06] py-3 last:border-0"><span className={`grid h-8 w-8 shrink-0 place-items-center rounded-lg ${tone === "mint" ? "bg-[#163b32] text-mint" : "bg-[#3a2b23] text-orange"}`}>{icon}</span><div className="min-w-0 flex-1"><p className="truncate text-sm text-white">{title}</p><p className="truncate text-[11px] text-muted">{subtitle}</p></div><span className={`shrink-0 text-sm font-semibold ${tone === "mint" ? "text-mint" : "text-orange"}`}>{tone === "mint" ? "+" : ""}<Money value={value} /></span></div>; }
function TransactionRow({ row, data }: { row: AnyRecord; data: DashboardData }) { const account = data.accounts.find((item) => item.id === row.accountId); return <div className="flex items-center gap-3 rounded-xl px-2 py-2.5 transition hover:bg-white/[.035]"><span className={`grid h-9 w-9 shrink-0 place-items-center rounded-xl ${row.type === "income" ? "bg-[#163b32] text-mint" : "bg-[#3a2824] text-orange"}`}>{row.type === "income" ? <ArrowDownLeft size={17} /> : <ArrowUpRight size={17} />}</span><div className="min-w-0 flex-1"><p className="truncate text-sm font-medium text-white">{row.description || (row.type === "income" ? "Entrada" : "Saída")}</p><p className="mt-0.5 truncate text-[11px] text-muted">{account?.name || "Conta"} · {shortDate(row.occurredAt)} · {labelOrigin(row.origin)}</p></div><p className={`text-sm font-semibold ${row.type === "income" ? "text-mint" : "text-orange"}`}>{row.type === "income" ? "+" : "−"}<Money value={row.amount} /></p></div>; }
function ChartTooltip({ active, payload, label }: AnyRecord) { if (!active || !payload?.length) return null; return <div className="rounded-xl border border-white/10 bg-[#10211e] px-3 py-2 text-xs shadow-xl"><p className="mb-1 text-muted">{label}</p>{payload.map((item: AnyRecord) => <p key={item.name} className="flex gap-3 text-white"><span>{item.name}</span><strong>{money(item.value)}</strong></p>)}</div>; }

function Modal({ title, onClose, children, wide = false }: { title: string; onClose: () => void; children: ReactNode; wide?: boolean }) { return <div className="fixed inset-0 z-[70] flex items-end justify-center bg-black/70 p-0 backdrop-blur-sm sm:items-center sm:p-5"><div className={`surface max-h-[92vh] w-full overflow-y-auto rounded-t-3xl p-5 sm:rounded-3xl sm:p-6 ${wide ? "max-w-2xl" : "max-w-lg"}`}><div className="mb-5 flex items-center justify-between"><h2 className="text-lg font-semibold text-white">{title}</h2><Button onClick={onClose} className="rounded-lg p-1.5 text-muted hover:bg-white/[.07] hover:text-white"><X size={19} /></Button></div>{children}</div></div>; }
function Field({ label, children, hint }: { label: string; children: ReactNode; hint?: string }) { return <label className="block"><span className="mb-1.5 block text-xs font-medium text-[#a8bfba]">{label}</span>{children}{hint && <span className="mt-1 block text-[10px] text-muted">{hint}</span>}</label>; }
function FormActions({ onClose, label = "Salvar" }: { onClose: () => void; label?: string }) { return <div className="mt-6 flex justify-end gap-2"><Button type="button" className="btn-secondary text-sm" onClick={onClose}>Cancelar</Button><Button className="btn-primary text-sm" type="submit">{label}</Button></div>; }

function QuickModal({ data, onClose, onDone, onNavigate }: { data: DashboardData; onClose: () => void; onDone: (message: string) => void; onNavigate: (id: Section) => void }) {
  const [mode, setMode] = useState<"income" | "expense" | "transfer" | "receivable">("income");
  const [busy, setBusy] = useState(false);
  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setBusy(true); const body = Object.fromEntries(new FormData(event.currentTarget).entries()); try { if (mode === "receivable") await api("/api/receivables", { method: "POST", body: JSON.stringify({ ...body, originalAmount: body.amount, description: body.description || "Valor emprestado" }) }); else await api("/api/transactions", { method: "POST", body: JSON.stringify({ ...body, type: mode }) }); onDone(mode === "transfer" ? "Transferência registrada sem alterar seu resultado." : "Movimentação registrada."); } catch (err) { onDone(err instanceof Error ? err.message : "Não foi possível salvar."); } finally { setBusy(false); } }
  const modeLabels = [{ id: "income", title: "Recebi dinheiro", icon: <ArrowDownLeft size={17} /> }, { id: "expense", title: "Gastei dinheiro", icon: <ArrowUpRight size={17} /> }, { id: "transfer", title: "Transferi dinheiro", icon: <ArrowLeftRight size={17} /> }, { id: "receivable", title: "Emprestei dinheiro", icon: <UserRound size={17} /> }] as const;
  return <Modal title="Novo lançamento" onClose={onClose}><div className="mb-5 grid grid-cols-2 gap-2 sm:grid-cols-4">{modeLabels.map((item) => <button key={item.id} onClick={() => setMode(item.id)} className={`flex flex-col items-center gap-2 rounded-xl border p-3 text-center text-[11px] font-medium ${mode === item.id ? "border-[#41d8b2]/60 bg-[#163c33] text-mint" : "border-white/[.08] text-muted hover:bg-white/[.04]"}`}>{item.icon}{item.title}</button>)}<button type="button" onClick={() => { onClose(); onNavigate("debts"); }} className="flex flex-col items-center gap-2 rounded-xl border border-white/[.08] p-3 text-center text-[11px] font-medium text-muted hover:bg-white/[.04]"><CreditCard size={17} />Paguei dívida</button></div><form onSubmit={submit} className="space-y-4"><Field label={mode === "receivable" ? "Pessoa / cliente" : "Valor"}>{mode === "receivable" ? <input name="person" className="input-dark" placeholder="Nome da pessoa" required /> : <div className="relative"><span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted">R$</span><input name="amount" className="input-dark pl-10 text-lg" inputMode="decimal" placeholder="0,00" required /></div>}</Field>{mode === "receivable" && <Field label="Valor original"><div className="relative"><span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted">R$</span><input name="amount" className="input-dark pl-10" inputMode="decimal" placeholder="0,00" required /></div></Field>}{mode === "transfer" ? <div className="grid gap-3 sm:grid-cols-2"><Field label="Conta de origem"><select name="fromAccountId" className="input-dark" required><option value="">Selecione</option>{data.accounts.filter((account) => account.status === "active").map((account) => <option key={account.id} value={account.id}>{account.name} · {money(account.balance)}</option>)}</select></Field><Field label="Conta de destino"><select name="toAccountId" className="input-dark" required><option value="">Selecione</option>{data.accounts.filter((account) => account.status === "active").map((account) => <option key={account.id} value={account.id}>{account.name}</option>)}</select></Field></div> : mode !== "receivable" ? <div className="grid gap-3 sm:grid-cols-2"><Field label="Categoria"><select name="categoryName" className="input-dark"><option value="">Sem categoria</option>{data.categories.filter((category) => category.kind === mode).map((category) => <option key={category.id} value={category.name}>{category.name}</option>)}</select></Field><Field label="Conta"><select name="accountId" className="input-dark" required><option value="">Selecione</option>{data.accounts.filter((account) => account.status === "active").map((account) => <option key={account.id} value={account.id}>{account.name}</option>)}</select></Field></div> : null}<div className="grid gap-3 sm:grid-cols-2"><Field label="Data"><input name={mode === "receivable" ? "dueDate" : "occurredAt"} type={mode === "receivable" ? "date" : "datetime-local"} className="input-dark" defaultValue={mode === "receivable" ? "" : new Date().toISOString().slice(0, 16)} /></Field>{mode === "receivable" ? <Field label="Descrição"><input name="description" className="input-dark" placeholder="Dinheiro emprestado" required /></Field> : <Field label="Origem"><select name="origin" className="input-dark"><option value="personal">Pessoal</option><option value="gbr">GBR Soluções</option></select></Field>}</div>{mode !== "receivable" && <Field label="Descrição"><input name="description" className="input-dark" placeholder={mode === "income" ? "Ex.: Instalação elétrica" : "Ex.: Combustível"} /></Field>}<FormActions onClose={onClose} label={busy ? "Salvando..." : "Salvar lançamento"} /></form><p className="mt-4 text-center text-[10px] text-muted">Transferências não entram como receita ou despesa.</p></Modal>;
}

function AccountsView({ data, run }: { data: DashboardData; run: (action: () => Promise<unknown>, success?: string) => Promise<void> }) { const [open, setOpen] = useState(false); const [editing, setEditing] = useState<AnyRecord | null>(null); const totals = [{ label: "Total físico", value: data.totals.physical }, { label: "Total digital", value: data.totals.digital }, { label: "Total investido", value: data.totals.investments }, { label: "Total geral", value: data.totals.available }]; return <div className="fade-in space-y-6"><SectionHeading title="Meu Dinheiro" description="Suas reservas e contas em um só lugar." action={<Button className="btn-primary flex items-center gap-2 text-sm" onClick={() => { setEditing(null); setOpen(true); }}><Plus size={16} /> Adicionar conta</Button>} /><div className="grid grid-cols-2 gap-3 lg:grid-cols-4">{totals.map((item, index) => <div className="surface rounded-2xl p-4" key={item.label}><p className="text-xs text-muted">{item.label}</p><p className={`mt-2 text-lg font-semibold ${index === 3 ? "text-white" : "text-mint"}`}><Money value={item.value} /></p></div>)}</div>{data.accounts.length === 0 ? <Empty title="Nenhuma conta cadastrada" description="Comece adicionando onde seu dinheiro fica guardado." action={<Button className="btn-primary text-sm" onClick={() => setOpen(true)}>Adicionar conta</Button>} /> : <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{data.accounts.map((account) => <div key={account.id} className={`surface rounded-2xl p-5 ${account.status !== "active" ? "opacity-60" : ""}`}><div className="flex items-start justify-between"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[#163c33] text-mint">{account.type === "investment" ? <Target size={19} /> : account.type === "physical" ? <Wallet size={19} /> : <Landmark size={19} />}</span><div className="flex gap-1"><button onClick={() => { setEditing(account); setOpen(true); }} className="rounded-lg p-2 text-muted hover:bg-white/[.06] hover:text-white"><Pencil size={15} /></button><button onClick={() => window.confirm("Arquivar esta conta?") && run(() => api(`/api/accounts/${account.id}`, { method: "DELETE" }), "Conta arquivada.")} className="rounded-lg p-2 text-muted hover:bg-[#3b2422] hover:text-red"><Trash2 size={15} /></button></div></div><h3 className="mt-5 font-semibold text-white">{account.name}</h3><p className="mt-1 text-xs text-muted">{labelType(account.type)} {account.status !== "active" && "· Arquivada"}</p><p className="mt-5 text-2xl font-semibold tracking-[-.04em] text-white"><Money value={account.balance} /></p>{account.description && <p className="mt-2 truncate text-xs text-muted">{account.description}</p>}</div>)}</div>}{open && <AccountModal account={editing} onClose={() => setOpen(false)} onSave={(body) => run(async () => { await api(editing ? `/api/accounts/${editing.id}` : "/api/accounts", { method: editing ? "PATCH" : "POST", body: JSON.stringify(body) }); setOpen(false); }, editing ? "Conta atualizada." : "Conta adicionada.")} />}</div>; }
function AccountModal({ account, onClose, onSave }: { account: AnyRecord | null; onClose: () => void; onSave: (body: AnyRecord) => void }) { function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); onSave(Object.fromEntries(new FormData(event.currentTarget).entries())); } return <Modal title={account ? "Editar conta" : "Nova conta"} onClose={onClose}><form onSubmit={submit} className="space-y-4"><Field label="Nome"><input name="name" className="input-dark" defaultValue={account?.name} placeholder="Ex.: Nubank" required /></Field><div className="grid gap-3 sm:grid-cols-2"><Field label="Tipo"><select name="type" defaultValue={account?.type || "digital"} className="input-dark"><option value="physical">Dinheiro físico</option><option value="digital">Conta digital</option><option value="investment">Investimento</option><option value="other">Outro</option></select></Field><Field label="Saldo atual"><input name="balance" className="input-dark" defaultValue={account?.balance || "0"} inputMode="decimal" placeholder="0,00" required /></Field></div><Field label="Descrição"><textarea name="description" className="input-dark min-h-20 resize-none" defaultValue={account?.description || ""} placeholder="Opcional" /></Field><FormActions onClose={onClose} label={account ? "Salvar alterações" : "Adicionar conta"} /></form></Modal>; }

function TransactionsView({ data, run }: { data: DashboardData; run: (action: () => Promise<unknown>, success?: string) => Promise<void> }) { const [filter, setFilter] = useState("all"); const [query, setQuery] = useState(""); const rows = data.transactions.filter((row) => (filter === "all" || row.type === filter || row.origin === filter) && `${row.description ?? ""}`.toLowerCase().includes(query.toLowerCase())); return <div className="fade-in space-y-5"><SectionHeading title="Movimentações" description="Tudo que entrou, saiu ou foi transferido." action={<Button className="btn-primary flex items-center gap-2 text-sm" onClick={() => document.querySelector<HTMLButtonElement>(".mobile-quick-trigger")?.click()}><Plus size={16} /> Nova movimentação</Button>} /><div className="surface rounded-2xl p-3"><div className="flex flex-col gap-3 sm:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-muted" size={16} /><input className="input-dark pl-9" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Filtrar por descrição..." /></div><select className="input-dark sm:w-44" value={filter} onChange={(event) => setFilter(event.target.value)}><option value="all">Todos os tipos</option><option value="income">Entradas</option><option value="expense">Saídas</option><option value="transfer">Transferências</option><option value="personal">Pessoal</option><option value="gbr">GBR Soluções</option></select></div></div>{rows.length ? <div className="surface overflow-hidden rounded-2xl"><div className="hidden grid-cols-[1fr_145px_125px_120px_32px] gap-3 border-b border-white/[.07] px-5 py-3 text-[10px] font-semibold uppercase tracking-wider text-muted md:grid"><span>Descrição</span><span>Categoria</span><span>Conta</span><span>Valor</span><span /></div>{rows.map((row) => <TransactionTableRow key={row.id} row={row} data={data} run={run} />)}</div> : <Empty title="Nada encontrado" description="Tente outro filtro ou registre uma nova movimentação." />}</div>; }
function TransactionTableRow({ row, data, run }: { row: AnyRecord; data: DashboardData; run: (action: () => Promise<unknown>, success?: string) => Promise<void> }) { const account = data.accounts.find((item) => item.id === row.accountId); const category = data.categories.find((item) => item.id === row.categoryId); return <div className="grid gap-2 border-b border-white/[.06] px-4 py-3 last:border-0 md:grid-cols-[1fr_145px_125px_120px_32px] md:items-center md:gap-3 md:px-5"><div className="flex items-center gap-3"><span className={`grid h-8 w-8 shrink-0 place-items-center rounded-lg ${row.type === "income" ? "bg-[#163b32] text-mint" : row.type === "expense" ? "bg-[#3a2824] text-orange" : "bg-[#29352f] text-[#c1d1ca]"}`}>{row.type === "income" ? <ArrowDownLeft size={15} /> : row.type === "expense" ? <ArrowUpRight size={15} /> : <ArrowLeftRight size={15} />}</span><div className="min-w-0"><p className="truncate text-sm text-white">{row.description || "Movimentação"}</p><p className="text-[11px] text-muted">{date(row.occurredAt)} · {labelOrigin(row.origin)}</p></div></div><span className="hidden truncate text-xs text-muted md:block">{category?.name || (row.type === "transfer" ? "Entre contas" : "Sem categoria")}</span><span className="hidden truncate text-xs text-muted md:block">{account?.name || "—"}</span><span className={`ml-11 text-sm font-semibold md:ml-0 ${row.type === "income" ? "text-mint" : row.type === "expense" ? "text-orange" : "text-muted"}`}>{row.type === "income" ? "+" : row.type === "expense" ? "−" : "↔ "}<Money value={row.amount} /></span><button onClick={() => window.confirm("Excluir esta movimentação? O saldo da conta será ajustado.") && run(() => api(`/api/transactions/${row.id}`, { method: "DELETE" }), "Movimentação excluída.")} className="absolute right-5 rounded-lg p-2 text-muted hover:text-red md:static"><Trash2 size={14} /></button></div>; }

function ReceivablesView({ data, run }: { data: DashboardData; run: (action: () => Promise<unknown>, success?: string) => Promise<void> }) { const [open, setOpen] = useState(false); const [pay, setPay] = useState<AnyRecord | null>(null); return <div className="fade-in space-y-6"><SectionHeading title="A Receber" description="Acompanhe clientes, empréstimos e serviços pendentes." action={<Button className="btn-primary flex items-center gap-2 text-sm" onClick={() => setOpen(true)}><Plus size={16} /> Adicionar recebível</Button>} /><div className="grid gap-3 sm:grid-cols-3"><MetricStrip label="Pendente" value={data.totals.toReceive} tone="mint" /><MetricStrip label="Recebido hoje" value={0} tone="white" /><MetricStrip label="Em atraso" value={data.receivables.filter((row) => row.computedStatus === "overdue").reduce((sum, row) => sum + row.remainingAmount, 0)} tone="orange" /></div>{data.receivables.length ? <div className="grid gap-4 lg:grid-cols-2">{data.receivables.map((row) => <div key={row.id} className="surface rounded-2xl p-5"><div className="flex items-start justify-between gap-3"><div><h3 className="font-semibold text-white">{row.person}</h3><p className="mt-1 text-xs text-muted">{row.description}</p></div><StatusBadge status={row.computedStatus} /></div><div className="mt-5 grid grid-cols-3 gap-2"><div><p className="text-[10px] uppercase text-muted">Original</p><p className="mt-1 text-sm text-white"><Money value={row.originalAmount} /></p></div><div><p className="text-[10px] uppercase text-muted">Recebido</p><p className="mt-1 text-sm text-mint"><Money value={row.receivedAmount} /></p></div><div><p className="text-[10px] uppercase text-muted">Restante</p><p className="mt-1 text-sm font-semibold text-orange"><Money value={row.remainingAmount} /></p></div></div><div className="mt-4 h-1.5 overflow-hidden rounded-full bg-white/[.07]"><div className="h-full rounded-full bg-mint" style={{ width: `${Math.min(100, (row.receivedAmount / Math.max(1, Number(row.originalAmount))) * 100)}%` }} /></div><div className="mt-4 flex items-center justify-between"><span className="text-xs text-muted">{row.dueDate ? `Previsto para ${date(row.dueDate)}` : "Sem data prevista"}</span>{row.remainingAmount > 0 && <Button className="btn-secondary text-xs" onClick={() => setPay(row)}>Registrar recebimento</Button>}</div></div>)}</div> : <Empty title="Nada a receber por enquanto" description="Cadastre valores pendentes para acompanhar pagamentos parciais." action={<Button className="btn-primary text-sm" onClick={() => setOpen(true)}>Adicionar recebível</Button>} />}{open && <ReceivableModal onClose={() => setOpen(false)} onSave={(body) => run(async () => { await api("/api/receivables", { method: "POST", body: JSON.stringify(body) }); setOpen(false); }, "Recebível adicionado.")} />}{pay && <PaymentModal title={`Receber de ${pay.person}`} amount={pay.remainingAmount} accounts={data.accounts} onClose={() => setPay(null)} onSave={(body) => run(async () => { await api(`/api/receivables/${pay.id}/pay`, { method: "POST", body: JSON.stringify(body) }); setPay(null); }, "Recebimento registrado.")} incoming />}</div>; }
function MetricStrip({ label, value, tone }: { label: string; value: unknown; tone: string }) { return <div className="surface rounded-2xl p-4"><p className="text-xs text-muted">{label}</p><p className={`mt-2 text-xl font-semibold ${tone === "mint" ? "text-mint" : tone === "orange" ? "text-orange" : "text-white"}`}><Money value={value} /></p></div>; }
function StatusBadge({ status }: { status: string }) { const map: AnyRecord = { pending: ["Pendente", "text-[#d3c59e] bg-[#393323]"], partial: ["Parcial", "text-[#a9c7ff] bg-[#202e49]"], received: ["Recebido", "text-mint bg-[#163c33]"], paid: ["Pago", "text-mint bg-[#163c33]"], overdue: ["Atrasado", "text-red bg-[#3d2525]"] }; const item = map[status] || [status, "text-muted bg-white/10"]; return <span className={`rounded-full px-2.5 py-1 text-[10px] font-semibold ${item[1]}`}>{item[0]}</span>; }
function ReceivableModal({ onClose, onSave }: { onClose: () => void; onSave: (body: AnyRecord) => void }) { function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); onSave(Object.fromEntries(new FormData(event.currentTarget).entries())); } return <Modal title="Novo valor a receber" onClose={onClose}><form onSubmit={submit} className="space-y-4"><Field label="Pessoa / cliente"><input name="person" className="input-dark" placeholder="Ex.: João da Silva" required /></Field><Field label="Descrição"><input name="description" className="input-dark" placeholder="Ex.: Serviço de instalação" required /></Field><div className="grid gap-3 sm:grid-cols-2"><Field label="Valor original"><input name="originalAmount" className="input-dark" inputMode="decimal" placeholder="0,00" required /></Field><Field label="Data prevista"><input name="dueDate" type="date" className="input-dark" /></Field></div><Field label="Observação"><textarea name="note" className="input-dark min-h-20 resize-none" /></Field><FormActions onClose={onClose} label="Adicionar recebível" /></form></Modal>; }
function PaymentModal({ title, amount, accounts, onClose, onSave, incoming }: { title: string; amount: number; accounts: AnyRecord[]; onClose: () => void; onSave: (body: AnyRecord) => void; incoming?: boolean }) { function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); onSave(Object.fromEntries(new FormData(event.currentTarget).entries())); } return <Modal title={title} onClose={onClose}><form onSubmit={submit} className="space-y-4"><div className="rounded-xl bg-[#122923] p-3 text-sm text-[#b8d5cd]">Valor restante: <strong className="text-white"><Money value={amount} /></strong></div><Field label="Valor do pagamento"><input name="amount" className="input-dark" defaultValue={amount} inputMode="decimal" required /></Field><Field label={incoming ? "Conta onde entrou" : "Conta de onde saiu"}><select name="accountId" className="input-dark" required><option value="">Selecione</option>{accounts.filter((account) => account.status === "active").map((account) => <option key={account.id} value={account.id}>{account.name} · {money(account.balance)}</option>)}</select></Field><FormActions onClose={onClose} label="Confirmar pagamento" /></form></Modal>; }

function DebtsView({ data, run }: { data: DashboardData; run: (action: () => Promise<unknown>, success?: string) => Promise<void> }) { const [open, setOpen] = useState(false); const [pay, setPay] = useState<AnyRecord | null>(null); return <div className="fade-in space-y-6"><SectionHeading title="Minhas Dívidas" description="Acompanhe o que falta pagar e os próximos vencimentos." action={<Button className="btn-primary flex items-center gap-2 text-sm" onClick={() => setOpen(true)}><Plus size={16} /> Adicionar dívida</Button>} /><div className="grid gap-3 sm:grid-cols-3"><MetricStrip label="Total de dívidas" value={data.debts.reduce((sum, row) => sum + Number(row.originalAmount), 0)} tone="white" /><MetricStrip label="Total pago" value={data.debts.reduce((sum, row) => sum + Number(row.paidAmount), 0)} tone="mint" /><MetricStrip label="Total restante" value={data.totals.debtTotal} tone="orange" /></div>{data.debts.length ? <div className="grid gap-4 lg:grid-cols-2">{data.debts.map((row) => <div key={row.id} className="surface rounded-2xl p-5"><div className="flex items-start justify-between"><div><h3 className="font-semibold text-white">{row.name}</h3><p className="mt-1 text-xs text-muted">{row.creditor} · {row.category}</p></div><StatusBadge status={row.computedStatus} /></div><div className="mt-5 flex items-end justify-between"><div><p className="text-[10px] uppercase text-muted">Restante</p><p className="mt-1 text-2xl font-semibold text-orange"><Money value={row.remainingAmount} /></p></div><div className="text-right text-xs text-muted"><p>Pago <span className="text-mint"><Money value={row.paidAmount} /></span></p><p className="mt-1">de <Money value={row.originalAmount} /></p></div></div><div className="mt-4"><Progress value={(row.paidAmount / Math.max(1, Number(row.originalAmount))) * 100} color="#ff9a65" /></div><div className="mt-4 flex items-center justify-between"><span className="text-xs text-muted">{row.nextDueDate ? `Próximo vencimento: ${date(row.nextDueDate)}` : "Sem vencimento"}</span>{row.remainingAmount > 0 && <Button className="btn-secondary text-xs" onClick={() => setPay(row)}>Registrar pagamento</Button>}</div></div>)}</div> : <Empty title="Nenhuma dívida cadastrada" description="Adicione compromissos para saber exatamente quanto falta quitar." action={<Button className="btn-primary text-sm" onClick={() => setOpen(true)}>Adicionar dívida</Button>} />}{open && <DebtModal onClose={() => setOpen(false)} onSave={(body) => run(async () => { await api("/api/debts", { method: "POST", body: JSON.stringify(body) }); setOpen(false); }, "Dívida adicionada.")} />}{pay && <PaymentModal title={`Pagar ${pay.name}`} amount={pay.remainingAmount} accounts={data.accounts} onClose={() => setPay(null)} onSave={(body) => run(async () => { await api(`/api/debts/${pay.id}/pay`, { method: "POST", body: JSON.stringify(body) }); setPay(null); }, "Pagamento registrado.")} />}</div>; }
function DebtModal({ onClose, onSave }: { onClose: () => void; onSave: (body: AnyRecord) => void }) { function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); onSave(Object.fromEntries(new FormData(event.currentTarget).entries())); } return <Modal title="Nova dívida" onClose={onClose}><form onSubmit={submit} className="space-y-4"><div className="grid gap-3 sm:grid-cols-2"><Field label="Nome"><input name="name" className="input-dark" placeholder="Ex.: Empréstimo" required /></Field><Field label="Credor"><input name="creditor" className="input-dark" placeholder="Ex.: Banco / pessoa" required /></Field></div><div className="grid gap-3 sm:grid-cols-2"><Field label="Valor original"><input name="originalAmount" className="input-dark" inputMode="decimal" placeholder="0,00" required /></Field><Field label="Categoria"><input name="category" className="input-dark" placeholder="Outros" /></Field></div><div className="grid gap-3 sm:grid-cols-2"><Field label="Parcelas"><input name="installments" type="number" min="1" className="input-dark" placeholder="Opcional" /></Field><Field label="Próximo vencimento"><input name="nextDueDate" type="date" className="input-dark" /></Field></div><Field label="Observação"><textarea name="note" className="input-dark min-h-20 resize-none" /></Field><FormActions onClose={onClose} label="Adicionar dívida" /></form></Modal>; }

function BillsView({ data, run }: { data: DashboardData; run: (action: () => Promise<unknown>, success?: string) => Promise<void> }) { const [open, setOpen] = useState(false); return <div className="fade-in space-y-6"><SectionHeading title="Contas a Pagar" description="Suas próximas obrigações, sem surpresas." action={<Button className="btn-primary flex items-center gap-2 text-sm" onClick={() => setOpen(true)}><Plus size={16} /> Nova conta</Button>} />{data.bills.length ? <div className="surface overflow-hidden rounded-2xl"><div className="hidden grid-cols-[1fr_130px_130px_120px_90px] gap-3 border-b border-white/[.07] px-5 py-3 text-[10px] font-semibold uppercase tracking-wider text-muted md:grid"><span>Conta</span><span>Vencimento</span><span>Recorrência</span><span>Valor</span><span>Status</span></div>{data.bills.map((bill) => <div key={bill.id} className="grid gap-2 border-b border-white/[.06] px-4 py-4 last:border-0 md:grid-cols-[1fr_130px_130px_120px_90px] md:items-center md:gap-3 md:px-5"><div><p className="text-sm font-medium text-white">{bill.name}</p><p className="mt-1 text-[11px] text-muted">{bill.category}</p></div><span className="text-xs text-muted">{date(bill.dueDate)}</span><span className="text-xs text-muted">{bill.recurrence === "none" ? "Sem recorrência" : bill.recurrence}</span><span className="text-sm font-semibold text-orange"><Money value={bill.amount} /></span><div><StatusBadge status={bill.computedStatus || bill.status} /></div></div>)}</div> : <Empty title="Nenhuma conta a pagar" description="Cadastre internet, faculdade, energia e outras obrigações." action={<Button className="btn-primary text-sm" onClick={() => setOpen(true)}>Adicionar conta</Button>} />}{open && <BillModal onClose={() => setOpen(false)} onSave={(body) => run(async () => { await api("/api/bills", { method: "POST", body: JSON.stringify(body) }); setOpen(false); }, "Conta cadastrada.")} />}</div>; }
function BillModal({ onClose, onSave }: { onClose: () => void; onSave: (body: AnyRecord) => void }) { function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); onSave(Object.fromEntries(new FormData(event.currentTarget).entries())); } return <Modal title="Nova conta a pagar" onClose={onClose}><form onSubmit={submit} className="space-y-4"><Field label="Nome"><input name="name" className="input-dark" placeholder="Ex.: Internet" required /></Field><div className="grid gap-3 sm:grid-cols-2"><Field label="Valor"><input name="amount" className="input-dark" inputMode="decimal" placeholder="0,00" required /></Field><Field label="Vencimento"><input name="dueDate" type="date" className="input-dark" required /></Field></div><div className="grid gap-3 sm:grid-cols-2"><Field label="Categoria"><input name="category" className="input-dark" placeholder="Casa" /></Field><Field label="Recorrência"><select name="recurrence" className="input-dark"><option value="none">Não recorrente</option><option value="monthly">Mensal</option><option value="yearly">Anual</option></select></Field></div><FormActions onClose={onClose} label="Adicionar conta" /></form></Modal>; }

function GoalsView({ data, run }: { data: DashboardData; run: (action: () => Promise<unknown>, success?: string) => Promise<void> }) { const [open, setOpen] = useState(false); return <div className="fade-in space-y-6"><SectionHeading title="Metas" description="Transforme seus planos em progresso visível." action={<Button className="btn-primary flex items-center gap-2 text-sm" onClick={() => setOpen(true)}><Plus size={16} /> Criar meta</Button>} />{data.goals.length ? <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{data.goals.map((goal) => <div key={goal.id} className="surface rounded-2xl p-5"><div className="flex items-start justify-between"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[#163c33] text-mint"><Target size={19} /></span><span className="text-sm font-semibold text-mint">{goal.progress}%</span></div><h3 className="mt-5 font-semibold text-white">{goal.name}</h3><p className="mt-1 text-xs text-muted">{goal.category}{goal.deadline ? ` · até ${date(goal.deadline)}` : ""}</p><div className="mt-5"><Progress value={goal.progress} /><div className="mt-2 flex justify-between text-xs"><span className="text-white"><Money value={goal.currentAmount} /></span><span className="text-muted">de <Money value={goal.targetAmount} /></span></div></div><p className="mt-4 text-xs text-muted">Faltam <span className="text-orange"><Money value={goal.remainingAmount} /></span></p></div>)}</div> : <Empty title="Nenhuma meta ainda" description="Crie uma meta para acompanhar seu próximo objetivo financeiro." action={<Button className="btn-primary text-sm" onClick={() => setOpen(true)}>Criar primeira meta</Button>} />}{open && <GoalModal onClose={() => setOpen(false)} onSave={(body) => run(async () => { await api("/api/goals", { method: "POST", body: JSON.stringify(body) }); setOpen(false); }, "Meta criada.")} />}</div>; }
function GoalModal({ onClose, onSave }: { onClose: () => void; onSave: (body: AnyRecord) => void }) { function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); onSave(Object.fromEntries(new FormData(event.currentTarget).entries())); } return <Modal title="Nova meta" onClose={onClose}><form onSubmit={submit} className="space-y-4"><Field label="Nome da meta"><input name="name" className="input-dark" placeholder="Ex.: Reserva financeira" required /></Field><div className="grid gap-3 sm:grid-cols-2"><Field label="Valor objetivo"><input name="targetAmount" className="input-dark" inputMode="decimal" placeholder="0,00" required /></Field><Field label="Já acumulado"><input name="currentAmount" className="input-dark" inputMode="decimal" placeholder="0,00" /></Field></div><div className="grid gap-3 sm:grid-cols-2"><Field label="Categoria"><input name="category" className="input-dark" placeholder="Reserva" /></Field><Field label="Prazo"><input name="deadline" type="date" className="input-dark" /></Field></div><Field label="Observação"><textarea name="note" className="input-dark min-h-20 resize-none" /></Field><FormActions onClose={onClose} label="Criar meta" /></form></Modal>; }

function ReportsView({ data }: { data: DashboardData }) { const [origin, setOrigin] = useState("all"); const rows = data.transactions.filter((row) => origin === "all" || row.origin === origin); const income = rows.filter((row) => row.type === "income").reduce((sum, row) => sum + Number(row.amount), 0); const expense = rows.filter((row) => row.type === "expense").reduce((sum, row) => sum + Number(row.amount), 0); const categories = data.categories.map((category) => ({ name: category.name, value: rows.filter((row) => row.categoryId === category.id && row.type === "expense").reduce((sum, row) => sum + Number(row.amount), 0) })).filter((row) => row.value > 0).sort((a, b) => b.value - a.value).slice(0, 6); return <div className="fade-in space-y-6"><SectionHeading title="Relatórios" description="Leitura simples da sua evolução financeira." action={<div className="flex gap-2"><select className="input-dark py-2 text-xs" value={origin} onChange={(event) => setOrigin(event.target.value)}><option value="all">Pessoal + GBR</option><option value="personal">Pessoal</option><option value="gbr">GBR Soluções</option></select><a className="btn-secondary flex items-center gap-2 text-xs" href="/api/export?format=csv"><Download size={14} /> CSV</a><a className="btn-secondary hidden items-center gap-2 text-xs sm:flex" href="/api/export?format=json"><FileDown size={14} /> JSON</a></div>} /><div className="grid gap-3 sm:grid-cols-3"><MetricStrip label="Total recebido" value={income} tone="mint" /><MetricStrip label="Total gasto" value={expense} tone="orange" /><MetricStrip label="Resultado" value={income - expense} tone="white" /></div><div className="grid gap-6 lg:grid-cols-[1.35fr_1fr]"><div className="surface rounded-2xl p-5 sm:p-6"><SectionHeading title="Evolução do saldo" description="Entradas e saídas por dia" /><div className="h-[280px]"><ResponsiveContainer width="100%" height="100%"><BarChart data={data.chart} margin={{ top: 8, right: 0, left: -22, bottom: 0 }}><CartesianGrid vertical={false} stroke="rgba(160,190,182,.08)" /><XAxis dataKey="day" axisLine={false} tickLine={false} tick={{ fill: "#718b85", fontSize: 11 }} /><YAxis axisLine={false} tickLine={false} tick={{ fill: "#718b85", fontSize: 10 }} /><Tooltip content={<ChartTooltip />} /><Bar dataKey="income" name="Entradas" fill="#41d8b2" radius={[4, 4, 0, 0]} /><Bar dataKey="expense" name="Saídas" fill="#ff9a65" radius={[4, 4, 0, 0]} /></BarChart></ResponsiveContainer></div></div><div className="surface rounded-2xl p-5 sm:p-6"><SectionHeading title="Maiores despesas" description="Por categoria" />{categories.length ? <div className="space-y-4">{categories.map((category, index) => <div key={category.name}><div className="mb-1.5 flex justify-between text-xs"><span className="text-white">{index + 1}. {category.name}</span><span className="text-orange"><Money value={category.value} /></span></div><Progress value={categories[0].value ? category.value / categories[0].value * 100 : 0} color="#ff9a65" /></div>)}</div> : <Empty title="Sem despesas registradas" description="As categorias aparecerão conforme você lançar movimentações." />}</div></div></div>; }

function PersonalView({ data }: { data: DashboardData }) { const personal = data.transactions.filter((row) => row.origin === "personal"); const gbr = data.transactions.filter((row) => row.origin === "gbr"); const totals = (rows: AnyRecord[]) => ({ income: rows.filter((row) => row.type === "income").reduce((sum, row) => sum + Number(row.amount), 0), expense: rows.filter((row) => row.type === "expense").reduce((sum, row) => sum + Number(row.amount), 0) }); const p = totals(personal); const g = totals(gbr); return <div className="fade-in space-y-6"><SectionHeading title="Pessoal x GBR" description="Uma separação gerencial, não contábil." /><div className="rounded-2xl border border-[#345147] bg-[#122a24] p-4 text-sm leading-6 text-[#b1d2c9]"><ShieldCheck className="mr-2 inline text-mint" size={17} />Marque a origem em cada lançamento para enxergar com clareza o que é pessoal e o que pertence à GBR Soluções.</div><div className="grid gap-4 lg:grid-cols-2"><OriginCard title="Pessoal" rows={p} color="mint" /><OriginCard title="GBR Soluções" rows={g} color="orange" /></div><div className="surface rounded-2xl p-5 sm:p-6"><SectionHeading title="Últimos lançamentos por origem" /><div className="space-y-1">{data.transactions.filter((row) => row.type !== "transfer").slice(0, 10).map((row) => <TransactionRow key={row.id} row={row} data={data} />)}</div></div></div>; }
function OriginCard({ title, rows, color }: { title: string; rows: AnyRecord; color: string }) { return <div className="surface rounded-2xl p-6"><div className="flex items-center gap-3"><span className={`grid h-10 w-10 place-items-center rounded-xl ${color === "mint" ? "bg-[#163c33] text-mint" : "bg-[#3a2b23] text-orange"}`}><UserRound size={19} /></span><div><h3 className="font-semibold text-white">{title}</h3><p className="text-xs text-muted">Visão acumulada</p></div></div><div className="mt-7 grid grid-cols-3 gap-3"><div><p className="text-xs text-muted">Receitas</p><p className="mt-1 text-sm font-semibold text-mint"><Money value={rows.income} /></p></div><div><p className="text-xs text-muted">Despesas</p><p className="mt-1 text-sm font-semibold text-orange"><Money value={rows.expense} /></p></div><div><p className="text-xs text-muted">Resultado</p><p className="mt-1 text-sm font-semibold text-white"><Money value={rows.income - rows.expense} /></p></div></div></div>; }

function SettingsView({ data, run }: { data: DashboardData; run: (action: () => Promise<unknown>, success?: string) => Promise<void> }) { const [settlementOpen, setSettlementOpen] = useState(false); const [passwordOpen, setPasswordOpen] = useState(false); return <div className="fade-in space-y-6"><SectionHeading title="Configurações" description="Seu perfil, segurança e preferências do GBR Bank." /><div className="grid gap-6 lg:grid-cols-[1.15fr_1fr]"><div className="surface rounded-2xl p-5 sm:p-6"><div className="mb-5 flex items-center gap-3"><span className="grid h-11 w-11 place-items-center rounded-full bg-[#2d8973] font-semibold text-white">{initials(data.profile.name)}</span><div><h3 className="font-semibold text-white">Perfil</h3><p className="text-xs text-muted">Como você aparece no painel</p></div></div><ProfileForm data={data} run={run} /></div><div className="space-y-6"><div className="surface rounded-2xl p-5 sm:p-6"><h3 className="font-semibold text-white">Segurança</h3><p className="mt-1 text-xs leading-5 text-muted">O acesso administrativo inicial é preparado no Supabase Auth. Esta primeira versão abre diretamente para o perfil privado configurado.</p><div className="mt-4 flex flex-wrap gap-2"><Button className="btn-secondary text-sm" onClick={() => setPasswordOpen(true)}>Alterar senha</Button><Button className="btn-secondary text-sm" onClick={() => run(() => api("/api/setup", { method: "POST" }), "Setup seguro verificado.")}><ShieldCheck className="mr-2 inline" size={15} /> Verificar configuração</Button></div></div><div className="surface rounded-2xl p-5 sm:p-6"><h3 className="font-semibold text-white">Meu acerto</h3><p className="mt-1 text-xs leading-5 text-muted">A meta só conta quando você registra o valor efetivamente separado.</p><div className="mt-4 flex items-center justify-between text-sm"><span className="text-muted">Meta definida</span><span className="text-white"><Money value={data.settlement?.targetAmount} /></span></div><Button className="btn-secondary mt-4 text-sm" onClick={() => setSettlementOpen(true)}>Ajustar valores</Button></div><div className="surface rounded-2xl p-5 sm:p-6"><h3 className="font-semibold text-white">Dados e backup</h3><p className="mt-1 text-xs leading-5 text-muted">Exporte uma cópia dos seus dados financeiros sempre que quiser.</p><div className="mt-4 flex flex-wrap gap-2"><a className="btn-secondary flex items-center gap-2 text-xs" href="/api/export?format=json"><FileDown size={14} /> Backup JSON</a><a className="btn-secondary flex items-center gap-2 text-xs" href="/api/export?format=csv"><Download size={14} /> Movimentações CSV</a></div></div></div></div>{settlementOpen && <SettlementModal settlement={data.settlement} onClose={() => setSettlementOpen(false)} onSave={(body) => run(async () => { await api("/api/settlement", { method: "PATCH", body: JSON.stringify(body) }); setSettlementOpen(false); }, "Meu acerto atualizado.")} />}{passwordOpen && <PasswordModal onClose={() => setPasswordOpen(false)} onSave={(body) => run(async () => { await api("/api/auth/password", { method: "POST", body: JSON.stringify(body) }); setPasswordOpen(false); }, "Senha alterada com segurança.")} />}</div>; }
function ProfileForm({ data, run }: { data: DashboardData; run: (action: () => Promise<unknown>, success?: string) => Promise<void> }) { function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const body = Object.fromEntries(new FormData(event.currentTarget).entries()); run(() => api("/api/profile", { method: "PATCH", body: JSON.stringify(body) }), "Perfil atualizado."); } return <form onSubmit={submit} className="space-y-4"><Field label="Nome"><input name="name" className="input-dark" defaultValue={data.profile.name} required /></Field><Field label="E-mail"><input name="email" type="email" className="input-dark" defaultValue={data.profile.email} /></Field><Field label="Usuário de acesso"><input name="username" className="input-dark" defaultValue={data.profile.username} /></Field><div className="grid gap-3 sm:grid-cols-2"><Field label="Moeda"><input className="input-dark" value="BRL · Real brasileiro" readOnly /></Field><Field label="Tema"><select name="theme" className="input-dark" defaultValue={data.settings?.theme || "dark"}><option value="dark">Escuro</option><option value="light">Claro (em breve)</option></select></Field></div><div className="flex justify-end"><Button className="btn-primary text-sm" type="submit">Salvar perfil</Button></div></form>; }
function SettlementModal({ settlement, onClose, onSave }: { settlement: AnyRecord | null; onClose: () => void; onSave: (body: AnyRecord) => void }) { function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); onSave(Object.fromEntries(new FormData(event.currentTarget).entries())); } return <Modal title="Meu acerto" onClose={onClose}><form onSubmit={submit} className="space-y-4"><Field label="Meta"><input name="targetAmount" className="input-dark" defaultValue={settlement?.targetAmount || "0"} inputMode="decimal" /></Field><Field label="Valor já separado"><input name="savedAmount" className="input-dark" defaultValue={settlement?.savedAmount || "0"} inputMode="decimal" /></Field><div className="rounded-xl bg-[#122923] p-3 text-xs leading-5 text-[#a7c9bf]">O valor separado é apenas uma referência gerencial. Ele não altera automaticamente o saldo das suas contas.</div><FormActions onClose={onClose} label="Salvar acerto" /></form></Modal>; }

function PasswordModal({ onClose, onSave }: { onClose: () => void; onSave: (body: AnyRecord) => void }) { function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); onSave(Object.fromEntries(new FormData(event.currentTarget).entries())); } return <Modal title="Alterar senha" onClose={onClose}><form onSubmit={submit} className="space-y-4"><p className="text-sm leading-5 text-muted">A senha é atualizada no Supabase Auth e nunca é salva pelo GBR Bank.</p><Field label="Nova senha"><input name="password" type="password" className="input-dark" minLength={8} autoComplete="new-password" required /></Field><Field label="Confirme a nova senha"><input name="confirmation" type="password" className="input-dark" minLength={8} autoComplete="new-password" required /></Field><FormActions onClose={onClose} label="Atualizar senha" /></form></Modal>; }
